def comps_of(g,bg):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for i in range(R):
        for j in range(C):
            if g[i][j]!=bg and not seen[i][j]:
                col=g[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<R and 0<=y<C and not seen[x][y] and g[x][y]!=bg:
                            seen[x][y]=True; stack.append((x,y))
                out.append((col,cells))
    return out

def is_thin_L(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    h,w=r1-r0+1,c1-c0+1
    if h<2 or w<2 or len(cells)!=h+w-1: return None
    grid=set(cells)
    # full row and full col
    for r in range(r0,r1+1):
        if all((r,c) in grid for c in range(c0,c1+1)):
            for c in range(c0,c1+1):
                if all((r2,c) in grid for r2 in range(r0,r1+1)):
                    return (r,c,h,w)
    return None

def exact_norm(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,c0=min(rs),min(cs)
    g={(r-r0,c-c0) for r,c in cells}
    h=max(r for r,c in g)+1; w=max(c for r,c in g)+1
    return tuple(tuple(1 if (i,j) in g else 0 for j in range(w)) for i in range(h))

